change.src/export.js:
function exportCsv(pedidos) {
  if (!pedidos.length) return 'Nenhum pedido encontrado.';
  const header = 'numero;cliente;data;valor';
  const rows = pedidos.map(p => [p.numero, p.cliente, p.data.toISOString().slice(0, 10), p.valor.toFixed(2).replace('.', ',')].join(';'));
  return [header, ...rows].join('\n');
}
module.exports = { exportCsv };

